import numpy as np
# rule candidates vs demo transcription
def apply(inp, thresh, keep2=True, overwrite0=True):
    I=np.array(inp); O=I.copy(); H,W=I.shape
    for y in range(H):
        for x in range(W):
            if I[y,x]==2:
                cnt=sum(0<=y+dy<H and 0<=x+dx<W and I[y+dy,x+dx]==3
                        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)])
                if cnt>=thresh:
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W:
                                if I[ny,nx]==2: continue
                                if I[ny,nx]==0 and not overwrite0: continue
                                O[ny,nx]=1
    return O

for thresh in (1,2,3,4):
    for ov0 in (True,False):
        pred=apply(inp,thresh,overwrite0=ov0)
        mism=np.argwhere(pred!=O)
        print(thresh, ov0, len(mism), mism[:8].tolist())
